}

/// Cue/loop/grid furniture for one deck's scrolling waveform. Columns are
/// screen pixels from the left edge, computed against the last view the UI sent.
class WaveHotCue {
  final int slot;
  final double column;
  final BigInt frame;

  const WaveHotCue({
    required this.slot,
    required this.column,
    required this.frame,
  });

  @override
  int get hashCode => slot.hashCode ^ column.hashCode ^ frame.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WaveHotCue &&
          runtimeType == other.runtimeType &&
          slot == other.slot &&
          column == other.column &&
          frame == other.frame;
}

/// The one palette both front-ends draw with. `0x00000000`-style ARGB values;
