/// A viewport-sized slice of the waveform pyramid, sent with one screen of
/// overscan on each side so Flutter only re-reads it when the playhead leaves
/// the safe middle. Bands are 0..255, one value per column.
class WaveStrip {
  final double startFrame;
  final double framesPerPixel;
  final int columns;
  final Uint8List leftLow;
  final Uint8List leftMid;
  final Uint8List leftHigh;
  final Uint8List rightLow;
  final Uint8List rightMid;
  final Uint8List rightHigh;

  const WaveStrip({
    required this.startFrame,
    required this.framesPerPixel,
    required this.columns,
    required this.leftLow,
    required this.leftMid,
    required this.leftHigh,
    required this.rightLow,
    required this.rightMid,
    required this.rightHigh,
  });

  @override
  int get hashCode =>
      startFrame.hashCode ^
      framesPerPixel.hashCode ^
      columns.hashCode ^
      leftLow.hashCode ^
      leftMid.hashCode ^
      leftHigh.hashCode ^
      rightLow.hashCode ^
      rightMid.hashCode ^
      rightHigh.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WaveStrip &&
          runtimeType == other.runtimeType &&
          startFrame == other.startFrame &&
          framesPerPixel == other.framesPerPixel &&
          columns == other.columns &&
          leftLow == other.leftLow &&
          leftMid == other.leftMid &&
          leftHigh == other.leftHigh &&
          rightLow == other.rightLow &&
          rightMid == other.rightMid &&
          rightHigh == other.rightHigh;
}

